/* qms-core.js — H 헬퍼 + Toast + Modal + App + Auth + Nav + Tbl + Cmt + UI [v2.394] */
"use strict";


const App={
  logo:'data:image/jpeg;base64,',
  notices:[
    {id:1,title:'2026년 5월 품질 목표 안내',body:'이번 달 수입검사 합격률 목표를 98% 이상으로 설정합니다. 검사 기준 숙지 바랍니다.',author:'관리자',date:'2026-05-01',expire:'2026-05-31',show:true},
    {id:2,title:'계측기 정기교정 일정 공지',body:'EQ-003, EQ-005 계측기 교정이 5월 15일 예정되어 있습니다. 해당 계측기 사용 부서 준비 바랍니다.',author:'품질팀',date:'2026-05-02',expire:'2026-05-16',show:true},
  ],
  files:{},
  /* [v2.394] 메뉴별 권한 저장소 */
  perms:{},
};

/* ══ DB ══ *//* ══ 헬퍼 ══ */
const H={
  e(s){return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')},
  d(d){if(!d)return'-';const dt=new Date(d);return`${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}-${String(dt.getDate()).padStart(2,'0')}`},
  n(n){return Number(n||0).toLocaleString('ko-KR')},
  today(){return this.d(new Date())},
  /* [v2.65] addDays — 날짜 문자열 + n일 */
  addDays(dateStr,n){
    const d=new Date(dateStr||new Date());
    d.setDate(d.getDate()+(n||0));
    return this.d(d);
  },
  _fmtSize(b){if(!b)return'0B';const u=['B','KB','MB','GB'];let i=0;while(b>=1024&&i<3){b/=1024;i++;}return b.toFixed(i>0?1:0)+u[i]},
  /* sha256: 비밀번호 해시 (Web Crypto API)
     [v2.394] A2안: 평문 대신 SHA-256 해시로 저장/비교 */
  async sha256(str){
    if(!str) return '';
    const buf=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(str));
    return Array.from(new Uint8Array(buf)).map(b=>b.toString(16).padStart(2,'0')).join('');
  },
  /* [v2.394 A안] 계측기 상태 자동 계산 — 차기교정일(next) 기준
     만료(D<0) → 교정만료  |  D-30 이내 → 교정중  |  나머지 → 정상 */
  equipStatus(next){
    if(!next) return '정상';
    const d=Math.ceil((new Date(next)-new Date())/(864e5));
    if(d<0)  return '교정만료';
    if(d<=30) return '교정중';
    return '정상';
  },
  /* [v2.394] 검사결과 배지 HTML 생성
     합격:초록 / 부분합격:청록 / 특채:주황 / 보류:회색 / 불합격:빨강 */
  inspBadge(v){
    const MAP={
      '합격':   'bgrn',
      '부분합격':'btea',
      '특채':   'bamb',
      '무검사': 'bpur',
      '보류':   'bgry',
      '불합격': 'bred',
    };
    const cls=MAP[v]||'bgry';
    return `<span class="badge ${cls}">${H.e(v||'-')}</span>`;
  },
};

/* ══ 토스트 ══ */
const Toast={
  show(msg,type='info',ms=3000){
    const ico={ok:'✅',err:'❌',warn:'⚠️',info:'ℹ️'};
    const el=document.createElement('div');el.className=`toast ${type}`;
    el.innerHTML=`<span>${ico[type]||'ℹ️'}</span><span>${H.e(msg)}</span>`;
    document.getElementById('tcont').appendChild(el);
    setTimeout(()=>{el.style.opacity='0';el.style.transition='opacity .3s';setTimeout(()=>el.remove(),300)},ms);
  }
};

/* ══ 모달 ══ */
const Modal={
  open({title,body,foot='',size='mlg'}={}){
    const box=document.getElementById('gmoBox');
    const mo=document.getElementById('gmo');
    /* 버그수정: 드래그 후 남은 인라인 스타일 완전 초기화
       position:fixed / alignItems 등이 남아 배경색 사라지는 원인 */
    box.removeAttribute('style');
    mo.removeAttribute('style');
    box.className=`mb ${size}`;
    document.getElementById('mTitle').innerHTML=title||'';
    document.getElementById('mBody').innerHTML=body||'';
    document.getElementById('mFoot').innerHTML=foot;
    mo.classList.remove('hidden');
    // 헤더 드래그 재바인딩 (매 open마다)
    const hd=box.querySelector('.mhd');
    if(hd) hd._dragBound=false;
    this._initDrag(box);
  },
  close(){
    const mo=document.getElementById('gmo');
    const box=document.getElementById('gmoBox');
    mo.classList.add('hidden');
    // 인라인 스타일 초기화 → 다음 open시 중앙 배치 보장
    box.removeAttribute('style');
    mo.removeAttribute('style');
  },
  /* 모달 드래그 이동 — 헤더(.mhd) 잡고 이동, 화면 밖 이탈 방지 */
  _initDrag(box){
    const hd=box.querySelector('.mhd');
    if(!hd||hd._dragBound) return;
    hd._dragBound=true;
    let ox=0,oy=0;
    const onDown=e=>{
      if(e.target.closest('button,input,select,textarea')) return;
      const r=box.getBoundingClientRect();
      ox=e.clientX-r.left; oy=e.clientY-r.top;
      box.classList.add('is-dragging');
      box.style.position='fixed';
      box.style.margin='0';
      box.style.left=r.left+'px'; box.style.top=r.top+'px';
      box.style.transform='none';
      const mo=document.getElementById('gmo');
      mo.style.alignItems='flex-start'; mo.style.justifyContent='flex-start';
      document.addEventListener('mousemove',onMove);
      document.addEventListener('mouseup',onUp);
    };
    const onMove=e=>{
      const nx=e.clientX-ox, ny=e.clientY-oy;
      const maxX=window.innerWidth-box.offsetWidth;
      const maxY=window.innerHeight-box.offsetHeight;
      box.style.left=Math.max(0,Math.min(nx,maxX))+'px';
      box.style.top=Math.max(0,Math.min(ny,maxY))+'px';
    };
    const onUp=()=>{
      box.classList.remove('is-dragging');
      document.removeEventListener('mousemove',onMove);
      document.removeEventListener('mouseup',onUp);
    };
    hd.addEventListener('mousedown',onDown);
  },
  confirm({title='확인',msg,onOk,danger=false}){
    this.open({title,size:'msm',
      body:`<div style="text-align:center;padding:10px 0"><div style="font-size:34px;margin-bottom:10px">${danger?'🗑️':'❓'}</div><p style="font-size:14px">${msg}</p></div>`,
      foot:`<button class="btn bout" onclick="Modal.close()">취소</button><button class="btn ${danger?'berr':'bpri'}" id="cfOk">확인</button>`
    });
    setTimeout(()=>{const b=document.getElementById('cfOk');if(b)b.onclick=()=>{Modal.close();onOk&&onOk()}},0);
  }
};

/* ══ 로고 ══ */
function applyLogo(src){
  App.logo=src;
  // 사이드바 로고
  const sbI=document.getElementById('sbLogoImg'),sbD=document.getElementById('sbLogoDef');
  if(sbI){sbI.src=src||'';sbI.style.display=src?'block':'none'}
  if(sbD)sbD.style.display=src?'none':'';
  // 홈화면은 App.logo를 직접 참조하므로 재렌더 불필요
}

/* ══ 인증 ══ */
const Auth={
  _u:null,_pwV:false,

  switchTab(name,btn){
    /* [v2.394] 탭 전환 시 이전 탭 입력값 초기화 */
    const clearIds={
      findId:['findIdName','findIdEmail'],
      findPw:['fpId','fpEmail','fpNewPw','fpNewPw2'],
      signup:['sgId','sgName','sgEmail','sgPw','sgPw2','sgDept','sgTel'],
    };
    /* 현재 탭 입력값 초기화 */
    Object.values(clearIds).flat().forEach(id=>{
      const el=document.getElementById(id);
      if(el) el.value='';
    });
    /* [v2.109] findId 결과 영역 초기화 — textContent='' 사용 시 내부 strong#foundId가
       영구 삭제되는 버그 수정 → display만 숨김 처리 */
    const res=document.getElementById('findIdResult');
    if(res) res.style.display='none';
    const errEl=document.getElementById('findIdError');
    if(errEl) errEl.style.display='none';
    /* findPw step1→step2 초기화 */
    const s1=document.getElementById('fpStep1'),s2=document.getElementById('fpStep2');
    if(s1)s1.style.display='block';
    if(s2)s2.style.display='none';
    /* 탭 전환 */
    document.querySelectorAll('.lo-tab').forEach(t=>t.classList.remove('on'));
    document.querySelectorAll('.lo-panel').forEach(p=>p.classList.remove('on'));
    if(btn)btn.classList.add('on');
    const m={login:'tabLogin',findId:'tabFindId',findPw:'tabFindPw',signup:'tabSignup'};
    const el=document.getElementById(m[name]);if(el)el.classList.add('on');
    ['errId','errPw'].forEach(id=>{const e=document.getElementById(id);if(e)e.style.display='none'});
    ['lid','lpw'].forEach(id=>{const e=document.getElementById(id);if(e)e.classList.remove('err')});
  },

  togglePw(){
    this._pwV=!this._pwV;
    const inp=document.getElementById('lpw'),ico=document.getElementById('pwToggle');
    if(inp)inp.type=this._pwV?'text':'password';
    if(ico)ico.textContent=this._pwV?'🙈':'👁️';
  },

  /* ── 로그인 처리 ──
     [v2.394] A2: SHA-256 해시 비교
     - admin/admin1234: 시스템 계정 (항상 허용)
     - 일반 사용자: DB.users에서 username 조회 후 password(해시) 비교 */
  async login(){
    const id=(document.getElementById('lid')?.value||'').trim();
    const pw=(document.getElementById('lpw')?.value||'').trim();
    const eId=document.getElementById('errId'),ePw=document.getElementById('errPw');
    const iId=document.getElementById('lid'),iPw=document.getElementById('lpw');
    let ok=true;
    if(!id){if(eId){eId.textContent='아이디를 입력하세요.';eId.style.display='block'}if(iId)iId.classList.add('err');ok=false;}
    else{if(eId)eId.style.display='none';if(iId)iId.classList.remove('err');}
    if(!pw){if(ePw){ePw.textContent='비밀번호를 입력하세요.';ePw.style.display='block'}if(iPw)iPw.classList.add('err');ok=false;}
    else{if(ePw)ePw.style.display='none';if(iPw)iPw.classList.remove('err');}
    if(!ok)return;
    /* [v2.394] admin 계정 하드코딩 복구 — SB 장애 시 비상 접근 보장 */
    if(id==='admin'){
      const curHash=await H.sha256(pw);
      const adminPwHash=await H.sha256('admin1234');
      /* admin 비밀번호는 sessionStorage에 저장된 변경값 우선 적용 */
      const savedAdmin=JSON.parse(sessionStorage.getItem('qms_admin')||'null');
      const validHash=savedAdmin?.pwHash||adminPwHash;
      if(curHash!==validHash){
        if(ePw){ePw.textContent='비밀번호가 올바르지 않습니다.';ePw.style.display='block';}
        if(iPw)iPw.classList.add('err');return;
      }
      const adminUser=savedAdmin?.info||{id:0,username:'admin',name:'시스템관리자',role:'admin',department:'IT팀',email:'admin@company.com'};
      this._doLoginSuccess(adminUser);
      return;
    }
    /* 일반 사용자: SB DB 조회 */
    if(!DB.users||DB.users.length===0) DB.users=await SB.getUsers();
    const user=DB.users.find(u=>u.username===id);
    if(!user){
      if(eId){eId.textContent='등록되지 않은 아이디입니다.';eId.style.display='block';}
      if(iId)iId.classList.add('err');return;
    }
    /* [v2.394] pending(승인대기) vs 비활성 구분 */
    /* [v2.394] pending: true/1/'true' 모두 처리 */
    if(user.pending&&user.pending!==0&&user.pending!=='0'&&user.pending!==false){
      if(eId){eId.textContent='승인 대기 중입니다. 관리자 승인 후 로그인하세요.';eId.style.display='block';}
      if(iId)iId.classList.add('err');return;
    }
    /* [v2.394] active===0 또는 null/undefined 모두 비활성 처리 */
    if(user.active===0||user.active===null||user.active===undefined){
      if(eId){eId.textContent='비활성화된 계정입니다. 관리자에게 문의하세요.';eId.style.display='block';}
      if(iId)iId.classList.add('err');return;
    }
    /* SHA-256 해시 비교 */
    const pwHash=await H.sha256(pw);
    const match=user.password===pwHash;
    if(match){
      this._doLoginSuccess(user);
    } else {
      if(ePw){ePw.textContent='비밀번호가 올바르지 않습니다.';ePw.style.display='block';}
      if(iPw)iPw.classList.add('err');
    }
  },

  /* 로그인 성공 공통 처리 */
  async _doLoginSuccess(user){
    this._cur='user'; this._u=user;
    sessionStorage.setItem('qms_auth',JSON.stringify({cur:'user',u:user}));
    /* [v2.129] 회사 로고 복원 — app_settings(logo_url)에서 로드.
       기존엔 base64를 App.logo(메모리)에만 저장해 영속화/복원이 전혀
       없었음. 처음 한 번만 영속 저장소에서 읽어와 적용 */
    try{
      if(typeof SB!=='undefined'&&SB.getAppSetting){
        const logoUrl=await SB.getAppSetting('logo_url');
        if(logoUrl) applyLogo(logoUrl);
      }
    }catch(e){console.warn('[Auth] 로고 복원 실패',e);}
    const roleLabel={'admin':'관','manager':'장','user':'사'};
    ['uav','uname','urole','tbuser'].forEach((el,i)=>{
      const e=document.getElementById(el);
      if(e)e.textContent=[(user.name||user.username||'?')[0],user.name||user.username,roleLabel[user.role]||'사용자',user.name||user.username][i];
    });
    /* [v2.394] 최근 로그인 시각 SB 업데이트 */
    if(_sb&&user.id) _sb.from('users').update({last_login:H.today()}).eq('id',user.id).then(()=>{});
    /* [v2.394] 관리자 로그인 시 비번찾기 알림 표시 */
    if(user.role==='admin'){
      try{
        const noti=JSON.parse(localStorage.getItem('qms_admin_noti')||'[]');
        const unread=noti.filter(n=>!n.read);
        if(unread.length>0){
          setTimeout(()=>{
            const msgs=unread.map(n=>'• '+n.username+' 님이 비밀번호 초기화를 요청했습니다. ('+n.time+')').join('<br>');
            Modal.open({title:'🔔 비밀번호 초기화 요청 알림',size:'mmd',
              body:'<div style="font-size:13px;line-height:2;color:#374151">'+msgs+'<br><br><span style="color:var(--tm);font-size:12px">설정 → 사용자 관리에서 비밀번호를 초기화하세요.</span></div>',
              foot:'<button class="btn bpri" onclick="Modal.close()">확인</button>'});
            noti.forEach(n=>n.read=true);
            localStorage.setItem('qms_admin_noti',JSON.stringify(noti));
          },800);
        }
      }catch(e){}
    }
    /* [v2.394] 로그인창 admin 이메일 업데이트 (admin 계정) */
    if(user.role==='admin'&&user.email){
      const eSpan=document.getElementById('adminContactEmail');
      if(eSpan) eSpan.textContent=user.email;
    }
    /* [v2.394] 권한 설정 복원 — sessionStorage에서 로드 */
    try{
      const _sp=sessionStorage.getItem('qms_perms');
      if(_sp) App.perms=JSON.parse(_sp);
    }catch(e){}
    /* [v2.394] 설정 메뉴: 관리자만 표시 */
    /* [v2.394] settings 모든 로그인 사용자에게 표시 */
    const settingsMenu=document.getElementById('ni_settings');
    if(settingsMenu) settingsMenu.style.display='';
    /* [v2.394] 게시기간 만료 공지 제외 */
    const _today=H.today();
    const active=App.notices.filter(n=>n.show&&(!n.expire||n.expire>=_today)&&(!n.date||n.date<=_today));
    if(active.length){
      const cnt=document.getElementById('npCount');if(cnt)cnt.textContent=`총 ${active.length}건`;
      const body=document.getElementById('npBody');
      if(body)body.innerHTML=active.map(n=>`
          <div class="npi" style="cursor:pointer" onclick="Auth.enterApp();Nav.go('mentions')" title="멘션함으로 이동"><div class="npi-t">${H.e(n.title)}</div>
          <div class="npi-b">${H.e(n.body)}</div>
          <div class="npi-m"><span>✍ ${H.e(n.author)}</span><span>📅 ${n.date} ~ ${n.expire}</span></div></div>`).join('');
      document.getElementById('npOverlay').classList.remove('hidden');
    } else { this.enterApp(); }
  },


  enterApp(){
    document.getElementById('npOverlay').classList.add('hidden');
    document.getElementById('loginOv').style.display='none';
    document.getElementById('app').classList.remove('hidden');
    /* [v2.394] 로그인 직후 DB 일괄 로드 후 홈 진입 */
    (async()=>{
      try{
        if(_sb){
          const [eq,ca,it,nc,us,me,docs,cars,vd] = await Promise.all([
            SB.getEquip(), SB.getCals(), SB.getItems(), SB.getNc(),
            SB.getUsers(), SB.getMentions(), SB.getDocs(), SB.getCars(),
            SB.getVendors()
          ]);
          if(eq)   DB.equip   = eq;
          if(ca)   DB.cals    = ca;
          if(it)   DB.items   = it;
          if(nc)   DB.nc      = nc;
          if(us)   DB.users   = us;
          if(me)   DB.mentions= me;
          if(docs) DB.docs    = docs;
          if(cars) DB.cars    = cars;
          if(vd)   DB.vendors = vd;
        }
      }catch(e){ console.warn('[enterApp] DB 로드 오류:', e); }
      Nav.go('home');
      Toast.show('로그인되었습니다.','ok');
      /* [v2.65] Magic Indicator 초기화 — 로그인 후 topbar DOM 완성 후 실행 */
      setTimeout(()=>{ if(typeof TopNav!=='undefined') TopNav._initIndicator(); }, 150);
      /* [v2.394] 로그인 시 keepalive 자동 실행 */
      setTimeout(async()=>{
        try{if(_sb){await _sb.from('users').select('id').limit(1);localStorage.setItem('qms_keepalive',new Date().toISOString().slice(0,16).replace('T',' '));}}catch(e){}},2000);
      /* [v2.394] 로그인 직후 멘션 배지 갱신 */
      setTimeout(()=>TopNav.updateMentionBadge(),500);
    })();
  },

  logout(){
    /* [v2.102] 로그아웃 확인 팝업 */
    const self=this;
    Modal.confirm({
      title:'로그아웃',
      msg:'<div style="text-align:center;padding:8px 0">'+
          '<div style="font-size:24px;margin-bottom:8px">👋</div>'+
          '<div style="font-size:14px;font-weight:500">로그아웃 하시겠습니까?</div>'+
          '</div>',
      onOk:function(){
        self._u=null;self._pwV=false;self._cur=null;
        sessionStorage.removeItem('qms_auth');
        sessionStorage.removeItem('qms_page');
        document.getElementById('app').classList.add('hidden');
        document.getElementById('loginOv').style.display='';
        document.getElementById('npOverlay').classList.add('hidden');
        const li=document.getElementById('lid'),lp=document.getElementById('lpw');
        if(li)li.value='';if(lp){lp.value='';lp.type='password';}
        const ico=document.getElementById('pwToggle');if(ico)ico.textContent='👁️';
        self.switchTab('login',document.querySelectorAll('.lo-tab')[0]);
        Toast.show('로그아웃되었습니다.','info');
      }
    });
  },

  /* ── 회원가입 [v2.394 복구] ──
     절차: 가입 신청 → DB에 pending(active=0) 저장 → 관리자가 설정>사용자관리에서 승인 */
  async signup(){
    const g=k=>(document.getElementById(k)?.value||'').trim();
    const id=g('suId'),name=g('suName'),pw=g('suPw'),pw2=g('suPw2');
    const errEl=document.getElementById('errSignup');
    const showErr=msg=>{if(errEl){errEl.textContent=msg;errEl.style.display='block';}};
    const clearErr=()=>{if(errEl){errEl.textContent='';errEl.style.display='none';}};
    clearErr();
    if(!id||id.length<4){showErr('아이디는 4자 이상이어야 합니다.');return}
    if(!/^[a-zA-Z0-9_]+$/.test(id)){showErr('아이디는 영문/숫자/_만 사용 가능합니다.');return}
    if(!name){showErr('이름을 입력하세요.');return}
    if(!pw||pw.length<8){showErr('비밀번호는 8자 이상이어야 합니다.');return}
    if(pw!==pw2){showErr('비밀번호가 일치하지 않습니다.');return}
    /* 중복 확인 */
    if(!DB.users||DB.users.length===0) DB.users=await SB.getUsers();
    if(id==='admin'||DB.users.some(u=>u.username===id)){
      showErr(`아이디 "${id}"는 이미 사용 중입니다.`);return;
    }
    const pwHash=await H.sha256(pw);
    const row={
      username:id, name,
      department:g('suDept'), email:g('suEmail'), tel:g('suTel'),
      password:pwHash,
      role:'user',
      active:0,          /* 관리자 승인 전: 비활성 */
      pending:true,      /* 승인 대기 표시 */
      created_at:H.today(), updated_at:H.today(),
    };
    const res=await SB.addUser(row);
    if(!res.ok) return;
    DB.users.push({id:res.id||Date.now(),...row});
    /* 가입 완료 메시지 */
    ['suId','suName','suPw','suPw2','suDept','suEmail','suTel'].forEach(k=>{
      const el=document.getElementById(k);if(el)el.value='';
    });
    this.switchTab('login',document.querySelectorAll('.lo-tab')[0]);
    Toast.show('가입 신청이 완료되었습니다.\n관리자 승인 후 로그인 가능합니다.','ok',5000);
  },

  /* ── 아이디 찾기 ── DB.users 연계 (이름+이메일로 username 검색) */
  async findId(){
    const name=(document.getElementById('findIdName')?.value||'').trim();
    const email=(document.getElementById('findIdEmail')?.value||'').trim();
    if(!name||!email){Toast.show('이름과 이메일을 입력하세요.','warn');return}
    /* admin 계정 */
    if(name==='시스템관리자'&&email.includes('@')){
      const r=document.getElementById('findIdResult'),fi=document.getElementById('foundId');
      if(fi)fi.textContent='admin';if(r)r.style.display='block';return;
    }
    /* [v2.109] DB.users 항상 최신 재조회 + trim/대소문자 무시 비교
       — RLS 정책으로 비로그인 조회가 막힐 경우 콘솔에 원인 표시 */
    const users=await SB.getUsers();
    console.log('[findId] getUsers 결과:', users?.length||0,'건');
    if(users&&users.length) DB.users=users;
    if(!DB.users||DB.users.length===0){
      console.warn('[findId] DB.users가 비어있습니다. users 테이블 RLS 정책에서 anon SELECT 권한을 확인하세요.');
    }
    const nameNorm=name.replace(/\s+/g,'');
    const emailNorm=email.toLowerCase();
    const user=(DB.users||[]).find(u=>
      (u.name||'').replace(/\s+/g,'')===nameNorm &&
      (u.email||'').toLowerCase()===emailNorm
    );
    const rEl=document.getElementById('findIdResult');
    const eEl=document.getElementById('findIdError');
    if(user){
      const fi=document.getElementById('foundId');
      if(fi)fi.textContent=user.username;
      if(rEl)rEl.style.display='block';
      if(eEl)eEl.style.display='none';
    } else {
      if(rEl)rEl.style.display='none';
      if(eEl)eEl.style.display='block';
      Toast.show('일치하는 계정을 찾을 수 없습니다.','err');
    }
  },

  /* ── 비밀번호 찾기 ──
     [v2.394] B2안: 관리자 초기화 방식
     실제 이메일 발송 인프라 없음 → 관리자에게 초기화 요청 안내
     아이디+이름 확인 후 안내 메시지 표시 */
  async findPwStep1(){
    const id=(document.getElementById('fpId')?.value||'').trim();
    const email=(document.getElementById('fpEmail')?.value||'').trim();
    if(!id||!email){Toast.show('아이디와 이메일을 입력하세요.','warn');return}
    /* admin 계정 */
    if(id==='admin'){
      Toast.show('관리자 계정은 비밀번호를 변경할 수 없습니다.','warn');return;
    }
    /* DB.users 조회 */
    if(!DB.users||DB.users.length===0) DB.users=await SB.getUsers();
    const user=DB.users.find(u=>u.username===id&&(u.email||'')=== email);
    const s1=document.getElementById('fpStep1'),s2=document.getElementById('fpStep2');
    if(user){
      if(s1)s1.style.display='none';if(s2)s2.style.display='block';
    } else {
      Toast.show('아이디 또는 이메일이 일치하는 계정을 찾을 수 없습니다.','err');
    }
  },

  findPwStep2(){
    /* B2안: 코드 인증 없이 관리자 문의 안내 */
    this.resetFindPw();
    this.switchTab('login',document.querySelectorAll('.lo-tab')[0]);
    /* contactAdmin 호출 */
    setTimeout(()=>this.contactAdmin(),200);
  },

  findPwStep2(){
    const code=(document.getElementById('fpCode')?.value||'').trim();
    const pw1=(document.getElementById('fpNewPw')?.value||'').trim();
    const pw2=(document.getElementById('fpNewPw2')?.value||'').trim();
    if(!code){Toast.show('인증 코드를 입력하세요.','warn');return}
    if(code!=='123456'){Toast.show('인증 코드가 올바르지 않습니다.','err');return}
    if(pw1.length<8){Toast.show('비밀번호는 8자 이상이어야 합니다.','warn');return}
    if(pw1!==pw2){Toast.show('비밀번호가 일치하지 않습니다.','warn');return}
    Toast.show('비밀번호가 변경되었습니다.','ok',5000);
    this.resetFindPw();this.switchTab('login',document.querySelectorAll('.lo-tab')[0]);
  },

  resetFindPw(){
    const s1=document.getElementById('fpStep1'),s2=document.getElementById('fpStep2');
    if(s1)s1.style.display='block';if(s2)s2.style.display='none';
    ['fpId','fpEmail','fpCode','fpNewPw','fpNewPw2'].forEach(id=>{const e=document.getElementById(id);if(e)e.value='';});
  },

  contactAdmin(fromPwFind=false){
    /* [v2.394] 비밀번호 찾기에서 호출 시 관리자 로그인 알림 저장 */
    if(fromPwFind){
      const fpId=(document.getElementById('fpId')?.value||'').trim();
      const req={type:'pw_reset',username:fpId,time:new Date().toLocaleString('ko-KR'),read:false};
      try{
        const arr=JSON.parse(localStorage.getItem('qms_admin_noti')||'[]');
        arr.unshift(req);
        localStorage.setItem('qms_admin_noti',JSON.stringify(arr.slice(0,50)));
      }catch(e){}
    }
    const adminEmail=localStorage.getItem('qms_admin_email')||(document.getElementById('adminContactEmail')?.textContent||'admin@company.com');
    const lo=document.getElementById('loginOv');
    let prev=document.getElementById('adminInqDlg');
    if(prev){prev.remove();return;}
    const dlg=document.createElement('div');
    dlg.id='adminInqDlg';
    dlg.style.cssText='position:absolute;inset:0;display:flex;align-items:center;justify-content:center;z-index:10;background:rgba(15,23,42,.45);border-radius:20px';
    dlg.innerHTML='<div style="background:#fff;border-radius:16px;padding:28px 28px 22px;max-width:340px;width:90%;box-shadow:0 20px 60px rgba(0,0,0,.3);text-align:center">'
      +'<div style="font-size:36px;margin-bottom:10px">💬</div>'
      +'<div style="font-size:15px;font-weight:700;color:#1e293b;margin-bottom:14px">시스템 관리자 문의</div>'
      +(fromPwFind?'<div style="background:#fef3c7;border:1px solid #f59e0b;border-radius:8px;padding:10px 14px;font-size:12px;color:#92400e;margin-bottom:12px">✅ 비밀번호 초기화 요청이 관리자에게 전달되었습니다.<br>관리자 로그인 시 알림이 표시됩니다.</div>':'')
      +'<div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:10px;padding:14px 16px;text-align:left;font-size:13px;line-height:2.2;color:#374151">'
      +'📧 이메일: '+adminEmail+'<br>🕐 운영시간: 평일 09:00 ~ 18:00'
      +'</div>'
      +'<button onclick="document.getElementById(&quot;adminInqDlg&quot;).remove()" style="margin-top:16px;padding:9px 28px;background:var(--pri);color:#fff;border:none;border-radius:8px;font-size:13px;font-weight:600;cursor:pointer;width:100%">확인</button>'
      +'</div>';
    if(lo) lo.appendChild(dlg);
    else{dlg.style.position='fixed';dlg.style.zIndex='99999';dlg.style.borderRadius='0';document.body.appendChild(dlg);}
  },

  cur(){return this._u}
};

/* ══ UI ══ */
const UI={
  _col:false,
  toggleSB(){
    const sb=document.getElementById('sb');
    if(window.innerWidth<=768){sb.classList.toggle('mobile-open');return}
    this._col=!this._col;sb.classList.toggle('col',this._col);
  },
  toggleMpop(){
    const pop=document.getElementById('mpop');
    const isHidden=pop.classList.contains('hidden');
    pop.classList.toggle('hidden');
    if(isHidden){
      /* [v2.394] 팝업 열 때 실시간 멘션 렌더 */
      UI.renderMpop();
    }
    document.getElementById('bdot').style.display='none';
  },
  renderMpop(){
    const list=document.getElementById('mpopList');
    if(!list) return;
    const me=Auth._cur||'admin';
    const isAdmin=Auth._u?.role==='admin';
    /* 미읽음 + 내 멘션 최신 10개 */
    const myMentions=(DB.mentions||[])
      .filter(m=>(m.to===me||(m.to_list||[]).includes(me)||isAdmin))
      .sort((a,b)=>(b.created_at||b.time||'').localeCompare(a.created_at||a.time||''))
      .slice(0,10);
    const unreadCnt=myMentions.filter(m=>!m.read).length;
    /* 헤더 배지 업데이트 */
    const mph=document.querySelector('.mph span');
    if(mph) mph.innerHTML='🔔 멘션 알림'+(unreadCnt?` <span style="background:var(--err);color:#fff;border-radius:10px;padding:1px 6px;font-size:10px">${unreadCnt}</span>`:'');
    if(!myMentions.length){
      list.innerHTML='<div style="text-align:center;padding:20px;color:var(--tm);font-size:12px">📭 멘션이 없습니다.</div>';
      return;
    }
    const PRIO_COLOR={urgent:'#ef4444',normal:'#3b82f6',low:'#94a3b8'};
    const TYPE_ICON={mention:'💬',task:'📋',notice:'📢',approval:'✅'};
    list.innerHTML=myMentions.map(m=>{
      const unread=!m.read;
      const dt=(m.created_at||m.time||'').replace('T',' ').slice(0,16);
      const pColor=PRIO_COLOR[m.priority||'normal'];
      const tIcon=TYPE_ICON[m.type||'mention']||'💬';
      const mpopClick='document.getElementById(\'mpop\').classList.add(\'hidden\');Pages._mentionReplyOpen('+m.id+')';
      return `<div class="mpi${unread?' mpi-unread':''}" style="cursor:pointer;background:${unread?'var(--bg2)':'transparent'}"
        onclick="${mpopClick}">
        <div class="mpf" style="display:flex;align-items:center;gap:6px">
          ${unread?'<span style="width:6px;height:6px;background:#ef4444;border-radius:50%;display:inline-block;flex-shrink:0"></span>':''}
          <span style="font-size:10px">${tIcon}</span>
          <span style="font-weight:600">${H.e(m.from||'?')}</span>
          <span style="color:var(--tm);font-size:10px">→ ${H.e((m.to_list||[m.to]).slice(0,1).join(','))}</span>
          <span style="margin-left:auto;font-size:9px;color:${pColor}">${m.priority==='urgent'?'🔴긴급':''}</span>
        </div>
        <div class="mpt">${H.e((m.text||'').slice(0,50))}${(m.text||'').length>50?'…':''}</div>
        <div class="mpd">${dt}</div>
      </div>`;
    }).join('');
  },
  markAllRead(){
    /* [v2.394] 모두 읽음 처리 */
    const me=Auth._cur||'admin';
    const isAdmin=Auth._u?.role==='admin';
    const unread=(DB.mentions||[]).filter(m=>
      !m.read&&(m.to===me||(m.to_list||[]).includes(me)||isAdmin)
    );
    Promise.all(unread.map(m=>SB.updateMention(m.id,{read:true}))).then(()=>{
      unread.forEach(m=>m.read=true);
      TopNav.updateMentionBadge();
      UI.renderMpop();
      Toast.show('모두 읽음 처리했습니다.','ok');
    });
  }
};

/* ══ 테이블 ══ */
const Tbl={
  /* [v2.394] 정렬 상태 저장 */
  _sortKey:null, _sortDir:1,

  render({el,cols,data,onDel,onRow,ps=20,page=1}={}){
    const c=typeof el==='string'?document.querySelector(el):el;
    if(!c)return;
    /* 정렬 적용 */
    let sorted=[...data];
    if(Tbl._sortKey){
      sorted.sort((a,b)=>{
        const va=a[Tbl._sortKey]??'', vb=b[Tbl._sortKey]??'';
        const na=parseFloat(va), nb=parseFloat(vb);
        const cmp=(!isNaN(na)&&!isNaN(nb))?(na-nb):String(va).localeCompare(String(vb));
        return cmp*Tbl._sortDir;
      });
    }
    const total=sorted.length, pages=Math.max(1,Math.ceil(total/ps));
    page=Math.min(Math.max(1,page),pages);
    const slice=sorted.slice((page-1)*ps,page*ps);
    const from=(page-1)*ps+1, to=Math.min(page*ps,total);
    /* 정렬 화살표 */
    const sortArrow=(key)=>{
      if(Tbl._sortKey!==key) return '<span style="opacity:.25;font-size:9px;margin-left:3px">↕</span>';
      return Tbl._sortDir===1
        ?'<span style="color:var(--pri);font-size:10px;margin-left:3px">↑</span>'
        :'<span style="color:var(--pri);font-size:10px;margin-left:3px">↓</span>';
    };
    /* 헤더 — 클릭 정렬 */
    const ths=`<th class="tc"><input type="checkbox" onchange="Tbl.chkAll(this)"></th><th class="tn">No</th>${cols.map(col=>`<th style="${col.w?`width:${col.w}`:''}${col.align?`;text-align:${col.align}`:''}${col.key?';cursor:pointer;user-select:none':''}" onclick="${col.key?`Tbl._sort('${col.key}')`:''}">` +`<span style="${col.req?'color:#dc2626;font-weight:700':''}">` +col.label+`</span>${col.req?'<span style="color:#dc2626"> *</span>':''}${col.key?sortArrow(col.key):''}</th>`).join('')}`;
    const trs=slice.length===0
      ?`<tr><td colspan="${cols.length+2}" style="text-align:center;padding:36px;color:var(--tm)">데이터가 없습니다.</td></tr>`
      :slice.map((row,i)=>`<tr data-id="${row.id}">
          <td class="tc"><input type="checkbox" class="rck" value="${row.id}" onchange="Tbl.onChk()"></td>
          <td class="tn">${(page-1)*ps+i+1}</td>
          ${cols.map(col=>{const v=row[col.key];const dv=(col.key==='updated_at'&&v&&v===row['created_at'])?'':v;return`<td style="${col.align?`text-align:${col.align}`:''}${onRow?';cursor:pointer':''}" onclick="${onRow?`Tbl._onRow(${row.id})`:''}">` +`${col.render?col.render(dv,row):H.e(dv??'')}</td>`;}).join('')}
        </tr>`).join('');
    /* 페이지네이션 */
    let pg='';
    if(pages>0){
      const s=Math.max(1,page-2), e2=Math.min(pages,s+4);
      const bs=[];
      bs.push(`<button class="pb" ${page===1?'disabled':''} onclick="Tbl._pg(1)" title="첫 페이지">«</button>`);
      bs.push(`<button class="pb" ${page===1?'disabled':''} onclick="Tbl._pg(${page-1})" title="이전">‹</button>`);
      if(s>1) bs.push(`<button class="pb" style="pointer-events:none;opacity:.4">…</button>`);
      for(let p=s;p<=e2;p++) bs.push(`<button class="pb${p===page?' on':''}" onclick="Tbl._pg(${p})">${p}</button>`);
      if(e2<pages) bs.push(`<button class="pb" style="pointer-events:none;opacity:.4">…</button>`);
      bs.push(`<button class="pb" ${page===pages?'disabled':''} onclick="Tbl._pg(${page+1})" title="다음">›</button>`);
      bs.push(`<button class="pb" ${page===pages?'disabled':''} onclick="Tbl._pg(${pages})" title="마지막">»</button>`);
      /* [v2.394] 페이지네이션: 정가운데 1줄 — 건수선택 | « ‹ 1 2 3 › » | N-M/전체 */
      pg=`<div class="pager" style="display:flex;justify-content:center;align-items:center;gap:8px;padding:8px 0;flex-wrap:nowrap">
        <select class="psel" onchange="Tbl._ps(this.value)" style="flex-shrink:0">
          ${[10,20,50,100].map(n=>`<option value="${n}"${ps===n?' selected':''}>${n}건</option>`).join('')}
        </select>
        <div class="pb-wrap" style="display:flex;gap:2px">${bs.join('')}</div>
        <div class="pi" style="flex-shrink:0;font-size:11px;color:var(--tm)">${from}–${to}/${total}건</div>
      </div>`;
    }
    /* [v2.394] 건수는 pager 안에 포함, 삭제버튼은 하단 별도 */
    const delBar=onDel
      ?`<div id="tbarDel" style="display:none;justify-content:center;margin-top:8px">
          <button class="btn berr bsm" onclick="Tbl.delSel()">🗑 선택 삭제</button>
        </div>`
      :'';
    c.innerHTML=`<div class="ts"><table class="dt"><thead><tr>${ths}</tr></thead><tbody>${trs}</tbody></table></div>${pg}`+delBar;
    /* onRow 이벤트 저장 */
    Tbl._onRowFn=onRow||null;
    Tbl._onDelFn=onDel||null;
    Tbl._curEl=el;
    Tbl._curCols=cols;
    Tbl._curData=data;
    Tbl._curPs=ps;
    Tbl._curPage=page;
  },

  /* [v2.394] 정렬 처리 */
  _sort(key){
    if(Tbl._sortKey===key){
      Tbl._sortDir*=-1;
    } else {
      Tbl._sortKey=key;
      Tbl._sortDir=1;
    }
    Tbl.render({el:Tbl._curEl,cols:Tbl._curCols,data:Tbl._curData,
      onRow:Tbl._onRowFn,onDel:Tbl._onDelFn,ps:Tbl._curPs,page:1});
  },
  /* [v2.394] onRow 이벤트 핸들러 — id→row 객체 변환 */
  _onRow(id){
    if(!Tbl._onRowFn) return;
    /* id로 _curData에서 row 객체 찾기 */
    const row=Tbl._curData?.find(r=>String(r.id)===String(id));
    Tbl._onRowFn(row||id);
  },
  _pg(p){
    Tbl.render({el:Tbl._curEl,cols:Tbl._curCols,data:Tbl._curData,
      onRow:Tbl._onRowFn,onDel:Tbl._onDelFn,ps:Tbl._curPs,page:p});
  },
  _ps(ps){
    Tbl.render({el:Tbl._curEl,cols:Tbl._curCols,data:Tbl._curData,
      onRow:Tbl._onRowFn,onDel:Tbl._onDelFn,ps:+ps,page:1});
  },
  chkAll(chk){document.querySelectorAll('.rck').forEach(c=>c.checked=chk.checked);this.onChk()},
  onChk(){
    const all=document.querySelectorAll('.rck'),chk=document.querySelectorAll('.rck:checked');
    const ca=document.querySelector('input[onchange*="chkAll"]');
    if(ca){ca.indeterminate=chk.length>0&&chk.length<all.length;ca.checked=chk.length===all.length&&all.length>0}
    const d=document.getElementById('tbarDel');if(d)d.style.display=chk.length?'flex':'none';
  },
  /* getSel: checkbox value는 문자열 → 숫자로 변환하여 id 타입 통일
     버그수정: ids.includes(i.id) 에서 '1'.includes(1)=false 문제 */
  getSel(){return Array.from(document.querySelectorAll('.rck:checked')).map(c=>Number(c.value))},
  delSel(){
    const ids=this.getSel();
    if(!ids.length){Toast.show('삭제할 항목을 선택하세요.','warn');return;}
    /* [v2.394] 삭제 경고 팝업 강화 */
    Modal.confirm({
      title:'🗑️ 선택 삭제 확인',
      msg:`<div style="text-align:center">
        <div style="font-size:32px;margin-bottom:8px">⚠️</div>
        <div style="font-size:15px;font-weight:700;margin-bottom:8px">선택한 <span style="color:#dc2626">${ids.length}건</span>을 삭제합니다.</div>
        <div style="font-size:12px;color:#64748b">삭제된 데이터는 복구가 어렵습니다.<br>계속 진행하시겠습니까?</div>
      </div>`,
      danger:true,
      onOk:()=>{if(Tbl._onDelFn)Tbl._onDelFn(ids)}
    });
  },
};

/* ══ 댓글 ══ */
/* ── 댓글/멘션 위젯 ──
   [v2.394] C1: SB.addMention 연동
   댓글은 mentions 테이블에 key(item-id, vendor-id 등)로 저장
   _d: 로컬 캐시 (key별) */
const Cmt={
  _d:{},

  /* 댓글 목록 렌더링 */
  async render(cont,key){
    const el=typeof cont==='string'?document.querySelector(cont):cont;
    if(!el)return;
    /* SB에서 로드 (없으면 로컬 캐시 사용) */
    if(!this._d[key]){
      const all=await SB.getMentions();
      /* key 필터 */
      this._d[key]=all.filter(m=>m.ref_key===key||m.ref===key||m.target===key||m.key===key);
    }
    this._drawList(el,key);
  },

  /* 댓글 목록 HTML 렌더 */
  _drawList(el,key){
    const items=this._d[key]||[];
    const me=Auth.cur();
    el.innerHTML=`<div class="csec">
      <div class="cst">💬 댓글 (${items.length})</div>
      <div class="clist">${items.length===0
        ?'<div style="text-align:center;padding:16px;color:var(--tm);font-size:13px">댓글이 없습니다.</div>'
        :items.map(c=>`
        <div class="ci">
          <div class="cm">
            <div class="cauth">
              <div class="cav">${(c.author||c.from_name||'?').charAt(0)}</div>
              <div>
                <div class="cun">${H.e(c.author||c.from_name||'사용자')}
                  <span style="color:var(--tm);font-size:11px">${H.e(c.dept||c.from_dept||'')}</span>
                </div>
                <div class="cdt">${H.e(c.time||c.created_at||'')}</div>
              </div>
            </div>
            ${me&&(me.username===(c.username||c.from)||me.role==='admin')
              ?`<button class="btn bxs berr" onclick="Cmt._del('${key}',${c.id})" title="삭제">🗑️</button>`:''}
          </div>
          <div class="cbody">${H.e(c.text||c.message||'').replace(/@(\S+)/g,'<span class="mtag">@$1</span>')}</div>
        </div>`).join('')}
      </div>
      <div class="ciw">
        <div class="cav" style="margin-top:3px">${(me?.name||'A').charAt(0)}</div>
        <div style="flex:1">
          <textarea id="ct-${key}" class="fc" placeholder="댓글 입력. @이름 으로 멘션 가능" rows="2"></textarea>
          <div style="display:flex;justify-content:flex-end;gap:5px;margin-top:5px">
            <button class="btn bsm bgh" onclick="document.getElementById('ct-${key}').value=''">취소</button>
            <button class="btn bsm bpri" onclick="Cmt.submit('${key}')">등록</button>
          </div>
        </div>
      </div>
    </div>`;
  },

  /* 댓글 등록 */
  async submit(key){
    const ta=document.getElementById(`ct-${key}`);
    if(!ta?.value.trim()){Toast.show('내용을 입력하세요.','warn');return}
    const me=Auth.cur();
    const row={
      ref_key:  key,
      message:  ta.value.trim(),
      from_name:me?.name||'사용자',
      from_dept:me?.dept||me?.department||'',
      from:     me?.username||'',
      read:     false,
      created_at:H.today(),
      /* mentions 테이블 호환 필드 */
      text:     ta.value.trim(),
      author:   me?.name||'사용자',
      dept:     me?.dept||me?.department||'',
      time:     '방금 전',
      key:      key,
    };
    /* SB 저장 */
    const res=await SB.addMention(row);
    if(!res.ok) return;
    /* 로컬 캐시 갱신 */
    if(!this._d[key]) this._d[key]=[];
    this._d[key].push({id:res.id||Date.now(),...row});
    ta.value='';
    Toast.show('등록되었습니다.','ok');
    /* 재렌더 */
    const p=ta.closest('.csec')?.parentElement;
    if(p) this._drawList(p,key);
  },

  /* 댓글 삭제 */
  async _del(key,id){
    Modal.confirm({title:'댓글 삭제',msg:'이 댓글을 삭제하시겠습니까?',danger:true,onOk:async()=>{
      await SB.deleteMention(id);
      if(this._d[key]) this._d[key]=this._d[key].filter(c=>c.id!==id);
      /* 재렌더 */
      const el=document.querySelector('#icmt,#vcmt,[id^="cmt"]');
      if(el) this._drawList(el,key);
      Toast.show('삭제되었습니다.','ok');
    }});
  },
};

/* ══ 파일 ══ */
/* ══════════════════════════════════════════════════════
   FM — 파일 관리 (File Manager)
   B안 완전 구현:
   1. Supabase Storage(qms-files 버킷) 실제 업로드
   2. 파일 메타데이터 sessionStorage 캐시 (새로고침 복원)
   3. 업로드 후 테이블 버튼 즉시 오렌지색 갱신
   4. 파일 바로보기 (PDF·이미지 → 새 탭, 기타 → 다운로드)
   5. 삭제 시 Storage + 캐시 동시 처리

   Supabase 테이블 (선택, 현재는 Storage+sessionStorage):
   file_attachments(id, key, name, size, path, url, date, created_at)
   ══════════════════════════════════════════════════════ */
const FM={
  /* ── 파일 목록 조회 (sessionStorage 캐시 → App.files) ── */
  get(k){
    if(!App.files[k]){
      /* sessionStorage에서 복원 (새로고침 후 유지) */
      try{
        const cached=sessionStorage.getItem(`qms_files_${k}`);
        if(cached) App.files[k]=JSON.parse(cached);
      }catch(e){}
    }
    return App.files[k]||[];
  },

  has(k){return this.get(k).length>0},

  /* ── 테이블 버튼 HTML 생성 ── */
  btn(k){
    const h=this.has(k);
    return `<button class="fbtn ${h?'has':'no'}" onclick="event.stopPropagation();FM.modal('${k}')">
      ${h?`📎 ${this.get(k).length}개`:'📎 없음'}
    </button>`;
  },

  /* ── 버튼 즉시 갱신 (버그1 수정: 업로드 후 오렌지 미반영) ──
     DOM에서 해당 key의 fbtn 버튼을 찾아 즉시 교체 */
  _refreshBtn(k){
    document.querySelectorAll('.fbtn').forEach(btn=>{
      if(btn.getAttribute('onclick')?.includes(`'${k}'`)){
        const h=this.has(k);
        btn.className=`fbtn ${h?'has':'no'}`;
        btn.innerHTML=h?`📎 ${this.get(k).length}개`:'📎 없음';
      }
    });
  },

  /* ── sessionStorage 캐시 저장 (버그2 수정: 새로고침 복원) ── */
  /* ── sessionStorage 캐시 저장 ──
     blob:// URL(isLocal=true)은 새로고침 시 만료 → url null로 변환 저장
     Supabase URL은 그대로 저장 (영구 유효) */
  _saveCache(k){
    try{
      const toSave=(App.files[k]||[]).map(f=>
        f.isLocal?{...f,url:null}:f
      );
      sessionStorage.setItem(`qms_files_${k}`,JSON.stringify(toSave));
    }catch(e){console.warn('[FM] 캐시 저장 실패',e);}
  },

  /* ── 파일 타입별 바로보기 판단 (버그3 수정) ── */
  _canPreview(name){
    const ext=(name.split('.').pop()||'').toLowerCase();
    const viewable=['pdf','jpg','jpeg','png','gif','webp','svg','bmp','txt','mp4','webm'];
    return viewable.includes(ext);
  },
  _isImage(name){
    const ext=(name.split('.').pop()||'').toLowerCase();
    return ['jpg','jpeg','png','gif','webp','svg','bmp'].includes(ext);
  },

  /* ── 파일 관리 모달 ── */
  modal(k){
    const files=this.get(k);
    const fileListHtml=files.length===0
      ?`<div style="text-align:center;padding:22px;color:var(--tm)">
          <div style="font-size:28px;margin-bottom:6px">📭</div>
          등록된 파일이 없습니다.
        </div>`
      :files.map((f,i)=>{
        const canView=this._canPreview(f.name);
        const isImg=this._isImage(f.name);
        /* previewBtn: url 있으면 바로보기, isLocal이면 로컬 ObjectURL로 보기, 없으면 비활성 */
        const previewBtn=f.url
          ?`<button class="btn bxs bout" onclick="FM._preview('${f.url}','${H.e(f.name)}',${isImg})" title="${f.isLocal?'로컬 미리보기(탭 유지 시 사용 가능)':'바로보기'}">
              ${isImg?'🖼️ 보기':'👁️ 보기'}
            </button>`
          :`<button class="btn bxs bout" style="opacity:.4" title="Supabase 연결 후 미리보기 가능">👁️</button>`;
        return`<div style="display:flex;align-items:center;gap:8px;padding:9px 11px;background:var(--bg);border-radius:var(--r);margin-bottom:6px">
          <div style="flex:1;min-width:0">
            <div style="font-size:13px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">
              ${canView?'📄':'📎'} ${H.e(f.name)}
              ${f.isLocal?`<span style="font-size:10px;color:var(--acc);margin-left:6px;font-weight:400">로컬</span>`:''}
            </div>
            <div style="font-size:11px;color:var(--tm)">${f.size||''} · ${f.date||''}</div>
          </div>
          <div style="display:flex;gap:5px;flex-shrink:0">
            ${previewBtn}
            ${f.url&&!f.isLocal
              ?`<a class="btn bxs bout" href="${f.url}" download="${H.e(f.name)}" onclick="event.stopPropagation()" title="다운로드">⬇️</a>`
              :`<button class="btn bxs bout" style="opacity:.4" title="Supabase 연결 후 다운로드 가능">⬇️</button>`}
            <button class="btn bxs berr" onclick="FM.del('${k}',${i})" title="삭제">🗑️</button>
          </div>
        </div>`;
      }).join('');

    Modal.open({title:'📎 파일 관리',size:'mmd',
      body:`<div id="flist" style="margin-bottom:12px">${fileListHtml}</div>
      <label style="display:flex;align-items:center;gap:10px;padding:11px;border:2px dashed var(--bd);border-radius:var(--r);cursor:pointer;transition:.15s"
        onmouseenter="this.style.borderColor='var(--acc)';this.style.background='#f0f9ff'"
        onmouseleave="this.style.borderColor='var(--bd)';this.style.background=''">
        <span style="font-size:22px">📁</span>
        <div>
          <div style="font-size:13px;font-weight:600">파일 선택 또는 드래그</div>
          <div style="font-size:11px;color:var(--tm)">모든 형식 지원 (최대 50MB)</div>
        </div>
        <input type="file" multiple style="display:none" onchange="FM.add('${k}',this)">
      </label>`,
      foot:`<button class="btn bout" onclick="Modal.close()">닫기</button>`
    });
  },

  /* ── 파일 바로보기 (버그3 수정) ──
     이미지: 모달 미리보기 / PDF·기타: 새 탭에서 열기 */
  /* ── 파일 바로보기 ──
     Supabase URL: 영구 유효
     blob:// URL: 탭 유지 중에만 유효, 새로고침 후 만료
     url=null: Supabase 연결 필요 안내 */
  _preview(url,name,isImg){
    if(!url){
      Toast.show('Supabase 연결 후 미리보기 가능합니다.\n(현재 로컬 파일은 탭 유지 시에만 미리보기 가능)','warn',4000);
      return;
    }
    /* blob URL 만료 감지: blob://로 시작하면 실제 접근 가능 여부 확인 */
    if(url.startsWith('blob:')){
      fetch(url,{method:'HEAD'}).catch(()=>{
        Toast.show('파일 URL이 만료되었습니다. 파일을 다시 첨부해주세요.','warn',4000);
        return;
      });
    }
    if(isImg){
      Modal.open({title:`🖼️ ${H.e(name)}`,size:'mlg',
        body:`<div style="text-align:center;padding:8px">
          <img src="${url}" alt="${H.e(name)}"
            style="max-width:100%;max-height:60vh;border-radius:var(--r);box-shadow:var(--shl)"
            onerror="this.parentElement.innerHTML='<div style=padding:20px;color:var(--err);text-align:center>이미지를 불러올 수 없습니다.<br><small>파일을 다시 첨부해주세요.</small></div>'">
        </div>`,
        foot:`<a class="btn bpri" href="${url}" target="_blank" rel="noopener">새 탭에서 열기</a>
              <button class="btn bout" onclick="Modal.close()">닫기</button>`
      });
    } else {
      /* PDF·기타: 새 탭에서 열기 */
      window.open(url,'_blank','noopener');
    }
  },

  /* ── 파일 업로드 (B안 핵심) ──
     1. Supabase Storage 실제 업로드
     2. sessionStorage 캐시 저장
     3. 테이블 버튼 즉시 갱신 (오렌지색)
     4. 모달 파일 목록 즉시 갱신 */
  async add(k,inp){
    if(!App.files[k]) App.files[k]=[];
    const rawFiles=Array.from(inp.files);
    if(!rawFiles.length) return;

    // 업로드 진행 표시
    document.getElementById('tcont')?.querySelectorAll('.toast').forEach(e=>e.remove());
    Toast.show(`${rawFiles.length}개 업로드 중...`,'info',60000);

    for(const f of rawFiles){
      /* Supabase Storage 업로드 시도 */
      const uploaded=await SB.uploadFile(k,f);
      if(uploaded){
        App.files[k].push(uploaded);
      } else {
        /* 폴백: 로컬 ObjectURL 생성
           - Supabase 미연결 또는 업로드 실패 시 사용
           - URL.createObjectURL(): 탭 열려있는 동안 미리보기 가능
           - 새로고침 후에는 url 만료 (sessionStorage는 name/size/date만 복원) */
        const localUrl=URL.createObjectURL(f);
        App.files[k].push({
          name:f.name,
          size:H._fmtSize(f.size),
          date:H.today(),
          path:null,
          url:localUrl,
          isLocal:true,
        });
      }
    }

    // 토스트 갱신
    document.getElementById('tcont')?.querySelectorAll('.toast').forEach(e=>e.remove());
    Toast.show(`${rawFiles.length}개 등록되었습니다.`,'ok');

    // sessionStorage 캐시 저장 (버그2 수정: 새로고침 후 복원)
    this._saveCache(k);

    // 테이블 버튼 즉시 갱신 (버그1 수정: 오렌지색 미반영)
    this._refreshBtn(k);

    // 모달 파일 목록 즉시 갱신
    Modal.close();
    setTimeout(()=>this.modal(k),80);
  },

  /* ── 파일 삭제 ──
     Supabase Storage + sessionStorage 캐시 동시 삭제 */
  async del(k,i){
    Modal.confirm({title:'파일 삭제',msg:'이 파일을 삭제하시겠습니까?',danger:true,
      onOk:async()=>{
        const f=App.files[k]?.[i];
        // Supabase Storage 삭제
        if(f?.path) await SB.deleteFile(f.path);
        // 로컬 목록에서 제거
        if(App.files[k]) App.files[k].splice(i,1);
        // 캐시 갱신
        this._saveCache(k);
        // 버튼 즉시 갱신
        this._refreshBtn(k);
        Toast.show('삭제되었습니다.','ok');
        // 모달 목록 갱신
        this.modal(k);
      }
    });
  },
};

/* ══════════════════════════════════════════════════════
   DateRange — 날짜 퀵버튼 헬퍼
   사용: DateRange.applyTo('fromId','toId','week')
   키: week, month, last_month, h1, h2, q1~q4
   ══════════════════════════════════════════════════════ */
const DateRange={
  get(key){
    const n=new Date();
    const y=n.getFullYear(),m=n.getMonth(),d=n.getDate();
    const fmt=dt=>`${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}-${String(dt.getDate()).padStart(2,'0')}`;
    const fd=(y2,m2,d2)=>fmt(new Date(y2,m2,d2));
    const ld=(y2,m2)=>fmt(new Date(y2,m2+1,0));
    const dow=n.getDay();
    const mon=dow===0?-6:(1-dow);
    switch(key){
      case 'week': return [fd(y,m,d+mon),fd(y,m,d+mon+6)];
      case 'month': return [fd(y,m,1),ld(y,m)];
      case 'last_month': return [fd(y,m-1,1),ld(y,m-1)];
      case 'h1': return [fd(y,0,1),fd(y,5,30)];
      case 'h2': return [fd(y,6,1),fd(y,11,31)];
      case 'q1': return [fd(y,0,1),fd(y,2,31)];
      case 'q2': return [fd(y,3,1),fd(y,5,30)];
      case 'q3': return [fd(y,6,1),fd(y,8,30)];
      case 'q4': return [fd(y,9,1),fd(y,11,31)];
      default: return ['',''];
    }
  },
  applyTo(fromId,toId,key){
    const [f,t]=this.get(key);
    const fe=document.getElementById(fromId),te=document.getElementById(toId);
    if(fe)fe.value=f; if(te)te.value=t;
    return {from:f,to:t};
  }
};

/* ══════════════════════════════════════════════════════
   기준정보 참조 검증 함수
   - _validateVendor(name): 거래처명이 거래처 등록에 있는지 확인
   - _validateItem(code):   품목코드가 품목 등록에 있는지 확인
   검사 등록 및 엑셀 일괄등록 시 호출
   ══════════════════════════════════════════════════════ */
function _validateVendor(name){
  if(!name)return true;
  return DB.vendors.some(v=>v.vendor_name===name);
}
function _validateItem(code){
  if(!code)return false;
  return DB.items.some(i=>i.item_code===code);
}

/* ══════════════════════════════════════════════════════
   TopNav — 상단 모듈 메뉴바 연동 객체
   - select(btn, mod): 모듈 탭 클릭 → 서브탭 렌더 + 사이드바 필터
   - syncFromPage(page): 페이지 이동 시 상단 탭 자동 동기화
   - _filterSidebar(mod): 해당 모듈의 사이드바 섹션만 표시
   ══════════════════════════════════════════════════════ */
/* ══ 상단 메뉴바 연동 (TopNav) ══ */
const TopNav={
  _map:{
    '기준정보':    [{label:'품목 등록',page:'items'},{label:'거래처 등록',page:'vendors'}],
    /* [v2.394] 시스템 탭 — 설정/사용자등록 분리 */
    '시스템':      [{label:'설정',page:'settings'},{label:'사용자 등록',page:'sysusers'}],
    '품질관리':    [{label:'품질현황 대시보드',page:'quality_dash'},{label:'수입검사',page:'insp_in'},{label:'공정검사',page:'insp_pr'},{label:'구매검사',page:'insp_pu'},{label:'외주검사',page:'insp_ou'},{label:'최종검사',page:'insp_fi'},{label:'부적합 관리',page:'nc'},{label:'8D Report',page:'nc_8d'},{label:'반품/폐기',page:'nc_dispose'},{label:'불량 트렌드',page:'nc_trend'}],
    '검사 고도화': [{label:'검사 기준서',page:'insp_std'},{label:'검사 성적서',page:'insp_cert'},{label:'LOT 추적성',page:'lot_trace'},{label:'Hold 관리',page:'insp_hold'},{label:'재검사 관리',page:'insp_reinsp'}],
    '공급업체 품질':[{label:'심사 계획 관리',page:'sqm_plan'},{label:'업체 심사',page:'sqm_audit'},{label:'업체 평가',page:'sqm_eval'},{label:'납품 이력',page:'sqm_delivery'},{label:'SQM 대시보드',page:'sqm_dash'}],
    '계측기관리':  [{label:'계측기 등록',page:'equip'},{label:'교정 관리',page:'cal'},{label:'MSA 분석',page:'msa'}],
    /* [v2.65] 제조설비관리 (EMS) */
    '제조설비관리':[
      {label:'설비 등록 관리',  page:'eq_mgmt'},
      {label:'예방정비(PM)',    page:'eq_pm'},
      {label:'고장/AS 관리',   page:'eq_as'},
      {label:'유지보수 비용',   page:'eq_cost'},
      {label:'설비 매뉴얼',    page:'eq_manual'},
      {label:'마이머신카드',   page:'eq_machine_card'},
      {label:'OEE/KPI 대시보드',page:'eq_dashboard'},
      {label:'부서별 보유현황', page:'eq_dept'},
    ],
    'SPC 통계관리':[{label:'관리도',page:'spc_chart'},{label:'공정능력(Cp/Cpk)',page:'spc_cpk'},{label:'파레토 분석',page:'spc_pareto'}],
    '개선활동':    [{label:'시정조치(CAR)',page:'car'},{label:'내부심사',page:'audit'}],
    '문서관리':    [{label:'문서 목록',page:'docs'},{label:'결재함',page:'doc_approval'},{label:'개정 이력',page:'doc_history_home'},{label:'지식 검색',page:'doc_search'},{label:'연관 문서',page:'doc_recommend'},{label:'현황 대시보드',page:'doc_dashboard'},{label:'배포 관리',page:'doc_distribution'},{label:'검토 주기',page:'doc_review_cycle'},{label:'기록 관리',page:'rec'}],
  },
  /* 모듈 선택 */
  select(btn, mod){
    // 상단 버튼 active
    document.querySelectorAll('.tb-mod').forEach(b=>b.classList.remove('on'));
    if(btn) btn.classList.add('on');
    // [v2.65] Magic Indicator 이동
    TopNav._moveIndicator(btn);
    // 서브탭 렌더링
    this._renderSubs(mod);
    // 사이드바 필터링
    this._filterSidebar(mod);
    // 첫 번째 세부메뉴로 이동
    const subs=this._map[mod]||[];
    if(subs.length>0) Nav.go(subs[0].page);
  },

  /* [v2.65] Magic Indicator 위치 계산 + 이동 */
  /* [v2.65] Magic Indicator pill 이동 — container 기준 left/width만 제어 */
  _moveIndicator(btn){
    const ind=document.getElementById('tbIndicator');
    if(!ind||!btn) return;
    const container=document.getElementById('tbModules');
    if(!container) return;
    const cRect=container.getBoundingClientRect();
    const bRect=btn.getBoundingClientRect();
    /* container padding(4px) 오프셋 포함 */
    const left=(bRect.left - cRect.left) + container.scrollLeft;
    const width=bRect.width;
    ind.style.left=left+'px';
    ind.style.width=width+'px';
  },

  /* [v2.65] 초기 indicator 위치 설정 (DOM 로드 후 호출) */
  _initIndicator(){
    /* [v2.65] getBoundingClientRect가 0이면 재시도 (DOM 렌더 대기) */
    const _try=(attempt)=>{
      const activeBtn=document.querySelector('.tb-mod.on');
      if(!activeBtn) return;
      const rect=activeBtn.getBoundingClientRect();
      if(rect.width===0 && attempt<5){
        setTimeout(()=>_try(attempt+1), 100);
        return;
      }
      TopNav._moveIndicator(activeBtn);
    };
    _try(0);
  },
  /* 서브탭 렌더링 */
  _renderSubs(mod){
    const el=document.getElementById('tbSubtabs');
    if(!el) return;
    const subs=this._map[mod]||[];
    el.innerHTML=subs.map(s=>`<div class="tb-subtab" data-p="${s.page}" onclick="TopNav._subClick(this,'${s.page}')">${s.label}</div>`).join('');
  },
  /* 서브탭 클릭 */
  _subClick(btn, page){
    document.querySelectorAll('.tb-subtab').forEach(b=>b.classList.remove('on'));
    if(btn) btn.classList.add('on');
    Nav.go(page);
  },
  /* 사이드바 섹션 필터링 */
  _filterSidebar(mod){
    const modToSection={
      '기준정보':'기준정보','품질관리':'품질관리','검사 고도화':'검사 고도화 (QA-B)',
      '공급업체 품질':'공급업체 품질 (SQM-E)','계측기관리':'계측기관리(MSA)',
      'SPC 통계관리':'SPC 통계관리 (C)','개선활동':'개선활동','문서관리':'문서관리',
      '제조설비관리':'제조설비관리',
    };
    const target=modToSection[mod]||'';
    document.querySelectorAll('.ns').forEach(ns=>{
      const nst=ns.querySelector('.nst');
      if(!nst) return;
      const txt=nst.textContent.trim();
      // 메인 섹션(홈/대시보드)은 항상 표시
      const isMain=(txt==='메인'||txt==='시스템');
      ns.style.display=(isMain||txt===target)?'':'none';
    });
  },
  /* 현재 page에서 모듈 역추적하여 상단 탭 동기화 */
  syncFromPage(page){
    for(const [mod,subs] of Object.entries(this._map)){
      if(subs.some(s=>s.page===page)){
        // 상단 버튼 active
        document.querySelectorAll('.tb-mod').forEach(b=>{
          b.classList.toggle('on', b.dataset.mod===mod);
        });
        this._renderSubs(mod);
        this._filterSidebar(mod);
        // 서브탭 active
        setTimeout(()=>{
          document.querySelectorAll('.tb-subtab').forEach(b=>{
            b.classList.toggle('on', b.dataset.p===page);
          });
        },50);
        return;
      }
    }
  },
  /* [v2.394] 멘션함 탭 클릭 — 다른 모듈과 충돌 없이 독립 이동 */
  selectMention(){
    /* 기존 active 탭 해제 */
    document.querySelectorAll('.tb-mod').forEach(m=>m.classList.remove('on'));
    document.getElementById('tbMentionBtn')?.classList.add('on');
    /* 사이드바 필터링 없이 바로 mentions 페이지로 이동 */
    Nav.go('mentions');
  },
  /* [v2.394] 멘션 미읽음 배지 업데이트 */
  updateMentionBadge(){
    const me=Auth._cur||'admin';
    const unread=(DB.mentions||[]).filter(m=>
      !m.read&&(m.to===me||(m.to_list||[]).includes(me)||Auth._u?.role==='admin')
    ).length;
    const badge=document.getElementById('tbMentionBadge');
    if(badge){
      badge.textContent=unread>9?'9+':unread||'';
      badge.style.display=unread?'flex':'none';
    }
    /* 사이드바 배지도 동시 업데이트 */
    const nb=document.getElementById('mnb');
    if(nb){nb.textContent=unread||'';nb.style.display=unread?'':'none';}
  },
};

/* ══════════════════════════════════════════════════════
   Nav — 페이지 네비게이션
   - Nav.go(page): 페이지 이동
     · home → 사이드바/탑바 숨김, pw.home-mode 추가
     · 기타 → 사이드바/탑바 표시, TopNav 동기화
   ══════════════════════════════════════════════════════ */
/* ══ 내비 ══ */
const Nav={
  go(page){
    /* C안: 현재 페이지를 sessionStorage에 저장 → F5 후 복원 */
    if(Auth._u) sessionStorage.setItem('qms_page', page);
    /* [v2.394] npOverlay(공지/알림 팝업) 열려있으면 닫기 */
    const _np=document.getElementById('npOverlay');
    if(_np&&!_np.classList.contains('hidden')) _np.classList.add('hidden');
    /* [v2.394] 멘션함 이동 시 배지 업데이트 */
    if(page==='mentions') setTimeout(()=>TopNav.updateMentionBadge(),300);

    /* [v2.394] 권한 기반 접근 제어 */
    const _role=Auth._u?.role||'viewer';
    const _roles=['admin','manager','user','viewer'];
    const _pKey=page+'_'+_role;
    const _adminOnly=['settings'];
    if(_adminOnly.includes(page)&&_role!=='admin'){
      Toast.show('관리자만 접근할 수 있습니다.','warn');return;
    }
    /* perms 설정 있으면 체크 */
    if(_role!=='admin'&&App.perms&&Object.keys(App.perms).length){
      const _perm=App.perms[_pKey];
      if(_perm===false){Toast.show('접근 권한이 없습니다.','warn');return;}
    }
    document.querySelectorAll('.ni').forEach(el=>el.classList.toggle('active',el.dataset.p===page));

    /* 홈: 사이드바 숨김 + 상단바 숨김, 전체 화면 */
    const sb=document.getElementById('sb');
    const topbar=document.querySelector('.topbar');
    const subtabs=document.getElementById('tbSubtabs');
    if(page==='home'){
      if(sb)sb.classList.add('hide');
      if(topbar)topbar.style.display='none';
      if(subtabs)subtabs.style.display='none';
    } else {
      if(sb){sb.classList.remove('hide');if(UI._col)sb.classList.add('col');else sb.classList.remove('col');}
      if(topbar)topbar.style.display='';
      if(subtabs)subtabs.style.display='';
      // 상단 메뉴바 동기화
      if(typeof TopNav!=='undefined') TopNav.syncFromPage(page);
    }

    const w=document.getElementById('pw');
    if(page!=='home') w.classList.remove('home-mode');
    w.innerHTML='<div class="spin"></div>';
    try{Pages[page]?Pages[page]():w.innerHTML=`<div class="card"><div class="es"><div class="es-icon">🚧</div><div>준비 중입니다.</div></div></div>`}
    catch(e){w.innerHTML=`<div class="card"><p style="color:var(--err)">오류: ${e.message}</p></div>`}
  }
};

/* ══ 페이지 ══ */
/* ════════════════════════════════════════════════════════════
   QnA — Q&A 팝업 컨트롤러 [v2.65]
   위치: topbar tb-right 날짜 오른쪽 ❓ 버튼
   기능: 매뉴얼/Q&A/팁 3탭 + 등록/답변/상태변경
   ════════════════════════════════════════════════════════════ */
const QnA = {

  _cat: 'all',       // 현재 탭
  _kw:  '',          // 검색어
  _rows: [],         // 전체 로드된 목록

  /* ── 팝업 열기/닫기 ── */
  toggle(){
    const pop = document.getElementById('qnaPop');
    if (!pop) return;
    const isHidden = pop.classList.contains('hidden');
    /* 다른 팝업 닫기 */
    document.getElementById('mpop')?.classList.add('hidden');
    pop.classList.toggle('hidden');
    if (isHidden) {
      this._cat = 'all';
      this._kw  = '';
      const searchEl = document.getElementById('qnaSearch');
      if (searchEl) searchEl.value = '';
      /* [v2.65] 전체 사용자 등록 가능 */
      const addBtn = document.getElementById('qnaAddBtn');
      if (addBtn) addBtn.style.display = '';
      this.load();
    }
  },

  /* ── 목록 로드 ── */
  async load(){
    const el = document.getElementById('qnaList');
    if (!el) return;
    el.innerHTML = '<div class="qna-empty">⏳ 로딩 중...</div>';
    this._rows = await SB.getQna({ category: this._cat === 'all' ? null : this._cat });
    this.render();
  },

  /* ── 탭 전환 ── */
  setTab(btn, cat){
    document.querySelectorAll('.qna-tab').forEach(b => b.classList.remove('on'));
    btn.classList.add('on');
    this._cat = cat;
    this._kw  = '';
    const searchEl = document.getElementById('qnaSearch');
    if (searchEl) searchEl.value = '';
    this.load();
  },

  /* ── 검색 ── */
  search(kw){
    this._kw = kw.toLowerCase();
    this.render();
  },

  /* ── 목록 렌더 ── */
  render(){
    const el = document.getElementById('qnaList');
    if (!el) return;

    let rows = this._rows || [];
    if (this._kw) {
      rows = rows.filter(r =>
        (r.title || '').toLowerCase().includes(this._kw) ||
        (r.body  || '').toLowerCase().includes(this._kw)
      );
    }

    if (!rows.length) {
      el.innerHTML = '<div class="qna-empty"><div style="font-size:28px;margin-bottom:6px">📭</div>등록된 항목이 없습니다.</div>';
      return;
    }

    const catLabel = { manual:'📖 매뉴얼', qna:'❓ Q&A', tip:'💡 팁' };
    const stLabel  = { open:'접수', in_progress:'처리중', resolved:'해결됨', closed:'닫힘' };
    const menuMap  = {
      docs:'문서관리', items:'품목', vendors:'거래처', insp_in:'수입검사',
      nc:'부적합', car:'시정조치', equip:'계측기', quality_dash:'품질현황'
    };

    el.innerHTML = rows.map(r => {
      const replyCnt = r.replies?.[0]?.count || 0;
      const menuStr  = r.menu_ref ? (menuMap[r.menu_ref] || r.menu_ref) : '';
      return `<div class="qna-item" onclick="QnA.openDetail(${r.id})">
        <div class="qna-item-top">
          <span class="qna-cat-badge qna-cat-${r.category}">${catLabel[r.category] || r.category}</span>
          ${r.is_pinned ? '<span class="qna-pin">📌</span>' : ''}
          <span class="qna-item-title">${H.e(r.title)}</span>
          <span class="qna-status-badge qna-st-${r.status}">${stLabel[r.status] || r.status}</span>
        </div>
        <div class="qna-item-meta">
          ${menuStr ? `<span>📂 ${H.e(menuStr)}</span>` : ''}
          <span>✍️ ${H.e(r.author)}</span>
          <span>${r.created_at ? new Date(r.created_at).toLocaleDateString('ko-KR') : ''}</span>
          <span>👁️ ${r.view_count || 0}</span>
          ${replyCnt > 0 ? `<span class="qna-reply-cnt">💬 ${replyCnt}</span>` : ''}
        </div>
      </div>`;
    }).join('');
  },

  /* ── 상세 보기 ── */
  async openDetail(id){
    const detail = document.getElementById('qnaDetail');
    const bodyEl  = document.getElementById('qnaDetailBody');
    const actEl   = document.getElementById('qnaDetailActions');
    if (!detail || !bodyEl) return;

    detail.classList.remove('hidden');
    bodyEl.innerHTML = '<div class="qna-empty">⏳ 로딩 중...</div>';
    actEl.innerHTML  = '';

    const r = await SB.getQnaById(id);
    if (!r) { bodyEl.innerHTML = '<div class="qna-empty">항목을 불러올 수 없습니다.</div>'; return; }

    const catLabel  = { manual:'📖 매뉴얼', qna:'❓ Q&A', tip:'💡 팁' };
    const stLabel   = { open:'접수됨', in_progress:'처리중', resolved:'해결됨', closed:'닫힘' };
    const stCls     = { open:'qna-st-open', in_progress:'qna-st-in_progress', resolved:'qna-st-resolved', closed:'qna-st-closed' };
    const role      = Auth._u?.role;
    const isAdmin   = role === 'admin' || role === 'manager';
    const me        = Auth._u?.name || Auth._u?.username || '관리자';
    const replies   = r.replies || [];

    /* 관리자 액션 버튼 */
    if (isAdmin) {
      actEl.innerHTML =
        `<select class="fsel" style="font-size:11px;padding:3px 6px" onchange="QnA.updateStatus(${r.id},this.value)">
          <option value="open"        ${r.status==='open'?'selected':''}>접수됨</option>
          <option value="in_progress" ${r.status==='in_progress'?'selected':''}>처리중</option>
          <option value="resolved"    ${r.status==='resolved'?'selected':''}>해결됨</option>
          <option value="closed"      ${r.status==='closed'?'selected':''}>닫힘</option>
        </select>
        <button class="btn bout bsm" onclick="QnA.openForm(${r.id})">✏️ 수정</button>
        <button class="btn bred bsm" onclick="QnA.deleteItem(${r.id})">🗑️ 삭제</button>`;
    }

    /* 본문 */
    bodyEl.innerHTML =
      `<div style="padding:18px 20px;overflow-y:auto;flex:1">
        <!-- 헤더 -->
        <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:10px">
          <span class="qna-cat-badge qna-cat-${r.category}">${catLabel[r.category]||r.category}</span>
          <span class="qna-status-badge ${stCls[r.status]||'qna-st-open'}">${stLabel[r.status]||r.status}</span>
          ${r.is_pinned ? '<span style="color:#f59e0b;font-size:12px">📌 고정</span>' : ''}
        </div>
        <div style="font-size:16px;font-weight:700;margin-bottom:6px">${H.e(r.title)}</div>
        <div style="font-size:12px;color:var(--tm);margin-bottom:14px;display:flex;gap:10px;flex-wrap:wrap">
          <span>✍️ ${H.e(r.author)}</span>
          <span>${r.created_at ? new Date(r.created_at).toLocaleDateString('ko-KR') : ''}</span>
          <span>👁️ ${r.view_count||0} 조회</span>
        </div>
        <div style="font-size:13px;line-height:1.7;white-space:pre-wrap;padding:14px;background:var(--bg2);border-radius:var(--r);margin-bottom:18px">${H.e(r.body||'')}</div>

        <!-- 답변 목록 -->
        <div style="font-size:13px;font-weight:600;margin-bottom:10px">
          💬 답변 ${replies.length}건
        </div>
        <div id="qnaReplies" style="display:flex;flex-direction:column;gap:8px;margin-bottom:18px">
          ${replies.map(rep =>
            `<div style="background:${rep.is_answer?'#f0fdf4':'var(--bg2)'};border:1px solid ${rep.is_answer?'#86efac':'var(--bd)'};border-radius:var(--r);padding:10px 14px">
              <div style="display:flex;align-items:center;gap:6px;margin-bottom:6px;flex-wrap:wrap">
                ${rep.is_answer ? '<span style="font-size:10px;font-weight:700;background:#d1fae5;color:#065f46;padding:1px 6px;border-radius:3px">✅ 공식 답변</span>' : ''}
                <span style="font-size:12px;font-weight:600">${H.e(rep.author)}</span>
                <span style="font-size:11px;color:var(--tm)">${rep.created_at ? new Date(rep.created_at).toLocaleDateString('ko-KR') : ''}</span>
                ${isAdmin ? `<button class="btn bxs berr" style="margin-left:auto" onclick="QnA.deleteReply(${rep.id},${r.id})">삭제</button>` : ''}
              </div>
              <div style="font-size:13px;line-height:1.6;white-space:pre-wrap">${H.e(rep.body)}</div>
            </div>`
          ).join('')}
          ${!replies.length ? '<div style="text-align:center;padding:16px;color:var(--tm);font-size:13px">아직 답변이 없습니다.</div>' : ''}
        </div>

        <!-- 답변 작성 -->
        <div style="border-top:1px solid var(--bd);padding-top:14px">
          <div style="font-size:12px;font-weight:600;margin-bottom:6px">답변 작성</div>
          <textarea id="qnaReplyText" rows="3" style="width:100%;box-sizing:border-box;padding:8px 10px;border:1px solid var(--bd);border-radius:var(--r);font-size:12px;background:var(--bg);color:var(--tx);resize:vertical" placeholder="답변 내용을 입력하세요..."></textarea>
          <div style="display:flex;justify-content:flex-end;gap:6px;margin-top:6px">
            ${isAdmin ? `<button class="btn bgrn bsm" onclick="QnA.submitReply(${r.id},true)">✅ 공식 답변으로 등록</button>` : ''}
            <button class="btn bpri bsm" onclick="QnA.submitReply(${r.id},false)">📝 답변 등록</button>
          </div>
        </div>
      </div>`;
  },

  closeDetail(){
    document.getElementById('qnaDetail')?.classList.add('hidden');
  },

  /* ── 답변 제출 ── */
  async submitReply(qnaId, isAnswer){
    const text = document.getElementById('qnaReplyText')?.value?.trim();
    if (!text) { Toast.show('답변 내용을 입력하세요.', 'warn'); return; }
    const me = Auth._u?.name || Auth._u?.username || '관리자';
    const r = await SB.addQnaReply(qnaId, text, me, isAnswer);
    if (r.ok) {
      Toast.show(isAnswer ? '✅ 공식 답변이 등록되었습니다.' : '답변이 등록되었습니다.', 'ok');
      this.openDetail(qnaId);
      this.load();
    }
  },

  /* ── 답변 삭제 ── */
  async deleteReply(replyId, qnaId){
    Modal.confirm({ title:'답변 삭제', msg:'답변을 삭제하시겠습니까?', danger:true,
      onOk: async () => {
        const r = await SB.deleteQnaReply(replyId);
        if (r.ok) { Toast.show('삭제되었습니다.','ok'); this.openDetail(qnaId); this.load(); }
      }
    });
  },

  /* ── 상태 변경 ── */
  async updateStatus(id, status){
    const r = await SB.updateQna(id, { status });
    if (r.ok) { Toast.show('상태가 변경되었습니다.','ok'); this.load(); }
  },

  /* ── 항목 삭제 ── */
  async deleteItem(id){
    Modal.confirm({ title:'Q&A 삭제', msg:'이 항목을 삭제하시겠습니까?', danger:true,
      onOk: async () => {
        const r = await SB.deleteQna(id);
        if (r.ok) {
          Toast.show('삭제되었습니다.','ok');
          this.closeDetail();
          this.load();
        }
      }
    });
  },

  /* ── 등록/수정 폼 ── */
  openForm(editId){
    const menuOptions = [
      {v:'',       l:'— 메뉴 선택 안함 —'},
      {v:'docs',   l:'문서관리'},
      {v:'items',  l:'품목 등록'},
      {v:'vendors',l:'거래처 등록'},
      {v:'insp_in',l:'수입검사'},
      {v:'nc',     l:'부적합'},
      {v:'car',    l:'시정조치'},
      {v:'equip',  l:'계측기'},
      {v:'quality_dash',l:'품질 대시보드'},
    ];

    const edit = editId ? (this._rows.find(r => r.id === editId) || null) : null;
    const isAdmin = Auth._u?.role === 'admin' || Auth._u?.role === 'manager';

    Modal.open({ title: edit ? 'Q&A 수정' : 'Q&A 등록', size:'mlg', body:
      `<div class="fg2">
        <div class="fgroup"><label class="fl req">분류</label>
          <select class="fc" id="qfCat">
            <option value="qna"    ${(!edit||edit.category==='qna')   ?'selected':''}>❓ Q&A / 오류 접수</option>
            <option value="tip"    ${edit?.category==='tip'   ?'selected':''}>💡 팁 & 기타</option>
            <option value="manual" ${edit?.category==='manual'?'selected':''}>📖 매뉴얼</option>
          </select>
        </div>
        <div class="fgroup"><label class="fl">관련 메뉴</label>
          <select class="fc" id="qfMenu">
            ${menuOptions.map(o => `<option value="${o.v}"${edit?.menu_ref===o.v?' selected':''}>${o.l}</option>`).join('')}
          </select>
        </div>
        <div class="fgroup ff"><label class="fl req">제목</label>
          <input class="fc" id="qfTitle" placeholder="제목을 입력하세요" value="${H.e(edit?.title||'')}">
        </div>
        <div class="fgroup ff"><label class="fl req">내용</label>
          <textarea class="fc" id="qfBody" rows="5" placeholder="내용을 입력하세요">${H.e(edit?.body||'')}</textarea>
        </div>
        <div class="fgroup"><label class="fl">고정글</label>
          <select class="fc" id="qfPin">
            <option value="0">일반</option>
            ${isAdmin ? `<option value="1"${edit?.is_pinned?' selected':''}>📌 고정</option>` : ''}
          </select>
        </div>
      </div>`,
      foot: `<button class="btn bout" onclick="Modal.close()">취소</button>
             <button class="btn bpri" onclick="QnA.saveForm(${editId||'null'})">저장</button>`,
    });
  },

  /* ── 등록/수정 저장 ── */
  async saveForm(editId){
    const title = document.getElementById('qfTitle')?.value?.trim();
    const body  = document.getElementById('qfBody')?.value?.trim();
    if (!title) { Toast.show('제목을 입력하세요.','warn'); return; }
    if (!body)  { Toast.show('내용을 입력하세요.','warn'); return; }

    const me = Auth._u?.name || Auth._u?.username || '관리자';
    const row = {
      category:  document.getElementById('qfCat')?.value  || 'qna',
      menu_ref:  document.getElementById('qfMenu')?.value || null,
      title, body,
      author:    me,
      is_pinned: document.getElementById('qfPin')?.value === '1',
    };

    let r;
    if (editId) {
      r = await SB.updateQna(editId, row);
    } else {
      row.status = 'open';
      r = await SB.addQna(row);
    }

    if (r.ok) {
      Toast.show(editId ? '수정되었습니다.' : '등록되었습니다.', 'ok');
      Modal.close();
      this.load();
    }
  },
};
/* [v2.65] QnA 전역 노출 */
window.QnA = QnA;


